import * as THREE from './vendor/three.module.js';
import {createPigForeman,PIG_FOREMAN_PAINT} from './pig-foreman.js';
import {createModelPaint} from './horse-model-paint.js';
import {GAME_CAMERA} from './hybrid-world.js';
import {unitArt} from './red-hats-art.js';
import {alphaBounds,rigidSpriteVertex} from './hybrid-sprites.js';
const $=id=>document.getElementById(id),host=$('scene'),renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x383838);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;host.append(renderer.domElement);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera();scene.add(new THREE.HemisphereLight(0xfff9ec,0x737775,2));const light=new THREE.DirectionalLight(0xfff2dc,2.3);light.position.set(3,5,4);scene.add(light);const fill=new THREE.DirectionalLight(0xffffff,.7);fill.position.set(-2,2,-3);scene.add(fill);
const loader=new THREE.TextureLoader(),greyStage=new URLSearchParams(location.search).get('stage')==='grey';
const rifleTexture=await loader.loadAsync('../assets/characters/lowpoly-proof/horse-worker-light-atlas.png');rifleTexture.colorSpace=THREE.SRGBColorSpace;
const paintedTexture=greyStage?null:await loader.loadAsync(PIG_FOREMAN_PAINT),variants={};
for(const [key,file] of [['28k','pig-foreman-author-data.json'],['10k','pig-foreman-10k-data.json']]){const data=await(await fetch('./'+file)).json(),horse=createPigForeman(data,rifleTexture);scene.add(horse.root);variants[key]={data,horse,modelPaint:paintedTexture?createModelPaint(renderer,horse,paintedTexture,{species:'pig-foreman'}):{material:horse.grey,setDebug(){}}};}
if(new URLSearchParams(location.search).get('mesh')==='10k'){$('mesh').value='10k';}
let {data,horse,modelPaint}=variants[$('mesh').value];
const sprites={};for(const weapon of ['rifle','unarmed']){const art=unitArt({species:'pig-foreman',outfit:'normal',weapon,stance:'standing'}),texture=await loader.loadAsync(art.src);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=texture.magFilter=THREE.NearestFilter;texture.generateMipmaps=false;
const source=document.createElement('canvas');source.width=art.width;source.height=art.height;const ctx=source.getContext('2d',{willReadFrequently:true});ctx.drawImage(texture.image,0,0);const bounds=alphaBounds(ctx.getImageData(0,0,art.width,art.height).data,art.width,art.height);
const sprite=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:texture,alphaTest:.4,toneMapped:false,side:THREE.DoubleSide}));scene.add(sprite);const p=sprite.geometry.attributes.position,uv=sprite.geometry.attributes.uv;for(let i=0;i<p.count;i++)p.setXYZ(i,...rigidSpriteVertex({heading:0},art,bounds,uv.getX(i)*art.width,(1-uv.getY(i))*art.height,GAME_CAMERA));sprite.geometry.computeBoundingSphere();sprite.visible=false;sprites[weapon]=sprite;}
function render(){const sprite=sprites[$('pose').value==='neutral'?'unarmed':'rifle'];for(const s of Object.values(sprites))s.visible=false;({data,horse,modelPaint}=variants[$('mesh').value]);window.lightHorse=horse;window.lightModelPaint=modelPaint;const close=$('close').checked,rifleOnly=$('pose').value==='rifle';host.style.height=close?'620px':'270px';host.style.width=close?'min(1000px,100%)':'min(660px,100%)';const w=host.clientWidth,h=host.clientHeight,ppu=close?300:58;renderer.setSize(w,h);renderer.setScissorTest(true);const heading=+$('heading').value;
 for(const v of Object.values(variants)){v.horse.pose($('pose').value==='neutral'?'neutral':'carry',heading);v.horse.setGrey($('grey').checked);v.horse.material.wireframe=v.horse.grey.wireframe=v.modelPaint.material.wireframe=$('wire').checked;if($('painted').checked&&!$('grey').checked)for(const part of v.horse.parts)part.material=v.modelPaint.material;v.modelPaint.setDebug($('coverage').checked);for(const p of v.horse.parts)p.material.wireframe=$('wire').checked;for(const part of v.horse.parts)part.visible=!rifleOnly;}
 $('left-label').textContent=$('reference').value==='baseline'?variants['28k'].data.triangles.toLocaleString()+' TRIANGLES':'ORIGINAL SPRITE';$('right-label').textContent=data.triangles.toLocaleString()+' TRIANGLES';
 for(let i=0;i<2;i++){const width=w/2;camera.left=-width/ppu/2;camera.right=width/ppu/2;camera.top=h/ppu/2;camera.bottom=-h/ppu/2;camera.near=.1;camera.far=30;const focus=new THREE.Vector3(0,.84,0),view=$('view').value,{azimuth:a,elevation:e}=view==='game'?GAME_CAMERA:{azimuth:{front:Math.PI/2,side:0,back:-Math.PI/2,three:Math.PI/4}[view],elevation:view==='three'?.12:0};camera.position.copy(focus).add(new THREE.Vector3(Math.sin(a)*Math.cos(e),Math.sin(e),Math.cos(a)*Math.cos(e)).multiplyScalar(5));camera.lookAt(focus);camera.updateProjectionMatrix();sprite.quaternion.copy(camera.quaternion);for(const v of Object.values(variants))v.horse.root.visible=false;sprite.visible=i===0&&$('reference').value==='sprite';if(i===1)horse.root.visible=true;else if($('reference').value==='baseline')variants['28k'].horse.root.visible=true;renderer.setViewport(i*width,0,width,h);renderer.setScissor(i*width,0,width,h);renderer.render(scene,camera);}
 renderer.setScissorTest(false);horse.root.visible=true;sprite.visible=false;const d=horse.diagnostics();$('status').textContent=`${d.triangles.toLocaleString()} character triangles + ${d.rifleTriangles.toLocaleString()} rifle · ${d.bones} bones · ${d.skinnedMeshes} weighted surfaces · ${ppu} CSS px/unit. Max palm/contact error: ${Math.max(0,...d.contacts.map(c=>c.error)).toFixed(6)} world units. Reference: ${data.sourceTriangles.toLocaleString()} triangles.`;
}
for(const [key,v] of Object.entries(variants))$('mesh').querySelector(`[value="${key}"]`).textContent=v.data.triangles.toLocaleString()+' triangles';
$('reference').querySelector('[value="baseline"]').textContent=variants['28k'].data.triangles.toLocaleString()+'-triangle author';
if(greyStage){$('painted').disabled=true;$('coverage').disabled=true;$('grey').checked=true;$('painted').checked=false;$('pose').value='neutral';}
for(const id of ['view','pose','close','grey','wire','heading','painted','coverage','mesh','reference'])$(id).addEventListener('input',render);new ResizeObserver(render).observe(host);render();window.lightHorse=horse;window.lightModelPaint=modelPaint;window.lightHorseDiagnostics=()=>({...horse.diagnostics(),pixelsPerUnit:host.clientHeight/(camera.top-camera.bottom),pose:$('pose').value,modelPaint:$('painted').checked,mesh:$('mesh').value});window.lightHorseReady=true;

// Screen-space coverage evidence for this viewer, not a claim of full surface coverage.
window.lightPaintCoverage=()=>{const previous=$('coverage').checked;$('coverage').checked=true;render();const gl=renderer.getContext(),w=gl.drawingBufferWidth,h=gl.drawingBufferHeight,pixels=new Uint8Array(w*h*4);gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,pixels);let mapped=0,borrowed=0,fallback=0;for(let y=0;y<h;y++)for(let x=Math.floor(w/2);x<w;x++){const k=(y*w+x)*4,r=pixels[k],g=pixels[k+1],b=pixels[k+2];if(g>r*1.2&&g>b*1.2)mapped++;else if(b>r*1.5&&b>g*1.5)borrowed++;else if(r>g*1.2&&b>g*1.2)fallback++;}$('coverage').checked=previous;render();return {mappedPixels:mapped,borrowedPixels:borrowed,fallbackPixels:fallback,fallbackPercent:100*fallback/Math.max(1,mapped+borrowed+fallback)};};

window.pigForemanVariants=variants;window.pigForemanRenderer=renderer;window.pigForemanRender=render;
